/** Draft geography quiz packs, 15 questions each (11 basic, 3 application, 1 challenge). */
export type HGGeoQuestion={id:string;level:'basic'|'application'|'challenge';prompt:string;options:[string,string,string,string];answer:0|1|2|3;explanation:string};
export type HGGeoQuizSet={lessonId:string;grade:6|7|8|9;strand:'geography';title:string;questions:HGGeoQuestion[];status:'draft'};
type GeoRaw=[string,string,string,string,string,number,string];
function buildGeo(prefix:string,rows:GeoRaw[]):HGGeoQuestion[]{return rows.map((r,i)=>({id:prefix+'-q'+String(i+1).padStart(2,'0'),level:i<11?'basic':i<14?'application':'challenge',prompt:r[0],options:[r[1],r[2],r[3],r[4]],answer:r[5] as 0|1|2|3,explanation:r[6]}));}
